select user_id into ob from public.restaurant_members where role='owner' and user_id<>oa and not exists(select 1 from public.platform_admins a where a.user_id=public.restaurant_members.user_id) limit 1;
select u.id into ca from auth.users u where not exists(select 1 from public.platform_admins a where a.user_id=u.id) and not exists(select 1 from public.restaurant_members m where m.user_id=u.id) order by u.created_at limit 1;
select u.id into cb from auth.users u where u.id<>ca and not exists(select 1 from public.platform_admins a where a.user_id=u.id) and not exists(select 1 from public.restaurant_members m where m.user_id=u.id) order by u.created_at limit 1;
